instant.source:
def instant(value: str | datetime) -> datetime:
    try:
        result = value if isinstance(value, datetime) else datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (ValueError, TypeError, AttributeError) as exc:
        raise ContractError("Timezone-aware timestamp required") from exc
    if result.tzinfo is None or result.utcoffset() is None:
        raise ContractError("Timezone-aware timestamp required")
    return result.astimezone(timezone.utc)

number.source:
def number(value, *, positive=False) -> Decimal:
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError) as exc:
        raise ContractError("Finite nonnegative number required") from exc
    if not result.is_finite() or result < 0 or (positive and result == 0):
        raise ContractError("Finite nonnegative number required")
    return result

quantity.source:
def quantity(value, *, positive=False) -> int:
    if type(value) is not int or value < (1 if positive else 0):
        raise ContractError("Nonnegative whole-share quantity required")
    return value

identity.source:
def identity(value: str) -> str:
    if not isinstance(value, str) or not value.strip() or len(value) > 256 or any(ord(c) < 32 for c in value):
        raise ContractError("Nonempty identity required")
    return value

stock_direction.source:
def stock_direction(probability: float) -> str:
    value = float(probability)
    if not math.isfinite(value) or not 0 <= value <= 1:
        raise ValueError("Stock direction requires a probability in [0, 1]")
    if value >= BULLISH_PROBABILITY:
        return "BULLISH"
    if value <= BEARISH_PROBABILITY:
        return "BEARISH"
    return "NO_EDGE"

size.source:
def size(*, symbol, side, hourly_reference, reference_version, score, score_version,
         inputs, half_share_ties=None, rounded_equality=None):
    if side not in {"BUY", "SELL"}:
        raise ContractError("BUY or SELL required")
    for value in (symbol, reference_version, score_version):
        identity(value)
    hourly = quantity(hourly_reference, positive=True)
    value = number(score)
    if value >= 1:
        raise ContractError("Raw 15m sizing score must be below one")
    raw = hourly * value
    if half_share_ties not in {None, "half_even", "half_up"}:
        raise ContractError("Unsupported half-share rule")
    if raw % 1 == number("0.5") and half_share_ties is None:
        raise UnresolvedPolicy("Half-share ties require an explicit sizing rule")
    rounding = ROUND_HALF_UP if half_share_ties == "half_up" else ROUND_HALF_EVEN
    desired = int(raw.to_integral_value(rounding=rounding))
    if rounded_equality not in {None, "allow"}:
        raise ContractError("No flooring or minimum-trade veto is selected")
    if desired == hourly and rounded_equality is None:
        raise UnresolvedPolicy("Nearest rounding equals hourly size; explicit handling required")
    return SizingExplanation(symbol, side, reference_version, score_version, hourly, str(value), str(raw),
                             desired, half_share_ties, rounded_equality, dict(inputs))

_finite.source:
def _finite(value, label):
    if isinstance(value, (bool, np.bool_)) or not isinstance(value, Real):
        raise ContractError(f"{label} must be a finite number")
    try:
        result = float(value)
    except (ValueError, TypeError, OverflowError) as exc:
        raise ContractError(f"{label} must be a finite number") from exc
    if not math.isfinite(result):
        raise ContractError(f"{label} must be a finite number")
    return result

_period.source:
def _period(value):
    if type(value) is not int or value < 1:
        raise ContractError("Indicator periods must be positive integers")
    return value

_clean.source:
def _clean(value):
    """JSON copies preserve all row provenance; optional missing fields are null."""
    if isinstance(value, Mapping):
        return {str(key): _clean(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_clean(item) for item in value]
    if isinstance(value, (pd.Timestamp, datetime)):
        return instant(value.to_pydatetime() if isinstance(value, pd.Timestamp) else value).isoformat()
    if isinstance(value, np.generic):
        return _clean(value.item())
    if value is None or value is pd.NA or value is pd.NaT:
        return None
    if isinstance(value, float) and not math.isfinite(value):
        return None
    return value

IndicatorSpec.source:
@dataclass(frozen=True)
class IndicatorSpec:
    name: str
    kind: str
    parameters: Mapping[str, object]
    derivatives: bool = False

    def validate(self):
        identity(self.name)
        if not self.name.replace("_", "").isalnum() or type(self.derivatives) is not bool:
            raise ContractError("Indicator names use letters, digits and underscores")
        required = {
            "ema": {"span", "adjust"}, "sma": {"window"},
            "rsi": {"window", "smoothing"},
            "bollinger": {"window", "deviations", "ddof"},
            "stochastic": {"window", "k_smoothing", "d_smoothing"},
            "momentum": {"lag"}, "vwap": {"window"},
            "atr": {"window", "smoothing"},
            "relative_volume": {"window", "baseline"},
        }
        if self.kind not in required or set(self.parameters) != required[self.kind]:
            raise ContractError("Unknown indicator or incomplete/unknown parameters")
        for key in {"window", "span", "lag", "k_smoothing", "d_smoothing"} & set(self.parameters):
            _period(self.parameters[key])
        if self.kind == "ema" and type(self.parameters["adjust"]) is not bool:
            raise ContractError("EMA adjust must be explicit boolean; seed is first observation")
        if self.kind in {"rsi", "atr"} and self.parameters["smoothing"] not in {"simple", "ewm_first"}:
            raise ContractError("Smoothing must be simple or first-observation EWM")
        if self.kind == "bollinger":
            if _finite(self.parameters["deviations"], "Band deviations") <= 0:
                raise ContractError("Band deviations must be positive")
            if type(self.parameters["ddof"]) is not int or self.parameters["ddof"] not in {0, 1}:
                raise ContractError("Bollinger ddof must be 0 or 1")
        if self.kind == "relative_volume" and self.parameters["baseline"] not in {"previous", "inclusive"}:
            raise ContractError("Relative-volume baseline must be previous or inclusive")
        return self

